import os,json,subprocess
from pathlib import Path
infra=Path("/srv/projects/VPS/archive/legacy-global-pm2-20261104")
telegram=Path("/srv/projects/telegram-robot-leads")
ipt=Path("/srv/projects/iptvpn-bot")
targets={"telegram-robot-leads":telegram/"archive/legacy-global-pm2-20261104","iptvpn_bot":ipt/"archive/legacy-global-pm2-20261104"}
logmap={"telegram-robot-leads-error.log":"telegram-robot-leads","telegram-robot-leads-out.log":"telegram-robot-leads","iptvpn-bot-error.log":"iptvpn_bot","iptvpn-bot-out.log":"iptvpn_bot"}
out={"project":"VPS","status":"BLOCKED","changed":False}
dirs=[];writes=[];moved=[];deleted_mixed=False
def svc():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ("ssh","nginx","pm2-telegram-robot-leads","pm2-iptvpn-bot","pink-vpn","lowcost-europa")}
try:
 if not infra.is_dir() or infra.is_symlink() or Path("/root/.pm2").exists():raise RuntimeError("infra_archive_not_unique")
 if any(not x.is_dir() or x.is_symlink() for x in (telegram,ipt)):raise RuntimeError("project_root_not_real")
 if any(p.exists() or p.is_symlink() for p in targets.values()):raise RuntimeError("destination_archive_collision")
 original=(infra/"dump.pm2").read_bytes();beforemixed=(infra/"dump.pm2.bak").read_bytes()
 snap=json.loads(original);backup=json.loads(beforemixed)
 if len(snap)!=1 or snap[0].get("name")!="telegram-robot-leads" or len(backup)!=2 or {a.get("name") for a in backup}!={"telegram-robot-leads","iptvpn_bot"}:raise RuntimeError("saved_snapshots_changed")
 if any(not (infra/"logs"/n).is_file() or (infra/"logs"/n).is_symlink() for n in logmap):raise RuntimeError("expected_log_identity_changed")
 baseline=svc()
 if baseline["pm2-telegram-robot-leads"]!="active" or baseline["pm2-iptvpn-bot"]!="active":raise RuntimeError("private_managers_not_running")
 for owner,p in targets.items():
  p.mkdir(mode=0o700);os.chmod(p,0o700);dirs.append(p)
  l=p/"logs";l.mkdir(mode=0o700);dirs.append(l)
 for owner in targets:
  app=[a for a in backup if a.get("name")==owner]
  filename=targets[owner]/"dump.backup.filtered.pm2"
  payload=json.dumps(app,separators=(",",":"),ensure_ascii=True).encode()
  fd=os.open(filename,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
  with os.fdopen(fd,"wb") as f:f.write(payload);f.flush();os.fsync(f.fileno())
  writes.append(filename)
  if json.loads(filename.read_text())!=app:raise RuntimeError("snapshot_partition_mismatch")
 s=infra/"dump.pm2";d=targets["telegram-robot-leads"]/"dump.pm2.original"
 os.rename(s,d);moved.append((s,d))
 for name,owner in logmap.items():
  s=infra/"logs"/name;d=targets[owner]/"logs"/name
  original_stat=s.stat()
  os.rename(s,d);moved.append((s,d))
  after=d.stat()
  if (original_stat.st_dev,original_stat.st_ino,original_stat.st_uid,original_stat.st_gid)!=(after.st_dev,after.st_ino,after.st_uid,after.st_gid):raise RuntimeError("legacy_log_identity_changed")
 if json.loads((targets["telegram-robot-leads"]/"dump.pm2.original").read_text())!=snap:raise RuntimeError("original_telegram_dump_moved_badly")
 for owner in targets:
  p=targets[owner]/"dump.backup.filtered.pm2"
  if json.loads(p.read_text())!=[a for a in backup if a.get("name")==owner]:raise RuntimeError("split_json_not_equivalent")
 if svc()!=baseline:raise RuntimeError("services_changed")
 (infra/"dump.pm2.bak").unlink();deleted_mixed=True
 out.update(status="HISTORY_SPLIT_VERIFIED",changed=True,telegram_logs=2,iptvpn_logs=2,private_snapshots_split=2,mixed_backup_removed=True,unattributed_logs_preserved_in_VPS=True,services_unchanged=True,original_file_inodes_preserved=True)
except Exception as e:
 out["reason"]=str(e)[:155]
 if deleted_mixed:
  try:
   f=infra/"dump.pm2.bak"
   fd=os.open(f,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
   with os.fdopen(fd,"wb") as x:x.write(beforemixed)
  except Exception:out["rollback"]="INCOMPLETE"
 for src,dst in reversed(moved):
  try:
   if dst.exists() and not src.exists():os.rename(dst,src)
  except Exception:out["rollback"]="INCOMPLETE"
 for p in reversed(writes):
  try:
   if p.is_file():p.unlink()
  except Exception:out["rollback"]="INCOMPLETE"
 for p in reversed(dirs):
  try:
   if p.is_dir() and not list(p.iterdir()):p.rmdir()
  except Exception:pass
print(json.dumps(out,sort_keys=True))
if out["status"]!="HISTORY_SPLIT_VERIFIED":raise SystemExit(3)
